const D = { energy:.6, scale:1, density:.5, speed:1, hue:32, numerals:.7, hatch:.6, x:.5, y:.5, style:'plate', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, H = ((P.hue%360)+360)%360, en = cl(P.energy,0,1);
const sp = .25 + .75*P.speed;
const lift = .55 + .45*K.intensity;
const bass = (S.b = (S.b||0)*.84 + (A.bass||0)*.16);

if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;

// ---- squaring the strip ---------------------------------------------------
// A skyline packer lays unequal integer squares into an endless vertical strip,
// always into the lowest-leftmost notch -- the greedy cousin of a perfect
// squared square. The skyline only ever rises, so the dissection is causal:
// finished squares scroll away and are never revisited.
const W = cl(Math.round(26/cl(P.scale,.5,2.2)), 10, 46);
const unit = width / W, VH = height/unit;
if (!S.sky || S.W !== W || S.seedUsed !== sd) {
  S.W = W; S.seedUsed = sd;
  S.sky = new Array(W).fill(0);
  S.sq = []; S.camY = 0; S.nid = 0;
}
S.camY += dt * sp * (.55 + .55*lift + .5*P.energy);

const dens = cl(P.density,0,1);
let guard = 0;
while (guard++ < 90) {
  let lo = Infinity, li = 0;
  for (let x=0;x<W;x++) if (S.sky[x] < lo) { lo = S.sky[x]; li = x; }
  if (lo > S.camY + VH + 2) break;
  let run = 0;
  while (li+run < W && S.sky[li+run] === lo) run++;
  let s = run;
  const r = fr(S.nid*3.71 + 1.3);
  if (s > 1) s = Math.max(1, s - Math.floor(r*s*(.28 + .58*dens)));
  for (let x=li;x<li+s;x++) S.sky[x] = lo + s;
  S.sq.push({ x: li, y: lo, s: s, id: S.nid++, b: S.camY });
}
if (S.sq.length > 40) {
  const keep = [];
  for (let i=0;i<S.sq.length;i++) if (S.sq[i].y + S.sq[i].s > S.camY - 3) keep.push(S.sq[i]);
  S.sq = keep;
}

// ---- styles ---------------------------------------------------------------
const glow = (sty==='xray');
function paper(){
  if (sty==='blueprint') return [212, 66, 38];
  if (sty==='riso')      return [44, 8, 94];
  if (glow)              return [(H+192)%360, 58, 5];
  if (sty==='slate')     return [214, 12, 18];
  return [(H+4)%360, 12, 89];
}
function ink(){
  if (sty==='blueprint') return [192, 20, 98];
  if (sty==='riso')      return [352, 72, 82];
  if (glow)              return [(H+156)%360, 34, 99];
  if (sty==='slate')     return [46, 6, 95];
  return [(H-16+360)%360, 58, 22];
}
function faceCol(q, hot, lam){
  const v = (.3 + .62*lam)*(.62+.5*en) + hot*.5;
  if (sty==='blueprint') return [ 206 + q*8, 44, cl(30 + 46*v, 6, 92) ];
  if (sty==='riso')      return [ (q<.5?352:205), cl(46 + 26*q,10,90), cl(58 + 42*v, 14, 100) ];
  if (glow)              return [ (H + 130 + q*110)%360, 42, cl(16 + 84*v, 2, 100) ];
  if (sty==='slate')     return [ 214, cl(6 + 8*q,0,26), cl(20 + 50*v, 3, 88) ];
  return [ (H + 2 + q*22)%360, cl(20 + 22*q, 4, 62), cl(52 + 44*v, 6, 98) ];
}

const pc = paper(); noStroke(); background(pc[0], pc[1], pc[2]);
const ic = ink();
const lang = K.t*.061*sp + .5*Math.sin(K.t*.0293);
const lgx = Math.cos(lang), lgy = Math.sin(lang);
const drift = u*.012*(Math.sin(K.t*.047) + .6*Math.sin(K.t*.113+1.9));

push();
translate((cl(P.x,.3,.7)-.5)*width*.5 + drift, (cl(P.y,.3,.7)-.5)*height*.28);
textAlign(CENTER, CENTER);
strokeJoin(MITER);
const hw = cl(P.hatch,0,1);

for (let i=0;i<S.sq.length;i++){
  const q2 = S.sq[i];
  const X = q2.x*unit, Y = height - (q2.y + q2.s - S.camY)*unit, D2 = q2.s*unit;
  if (Y > height + unit*2 || Y + D2 < -unit*2) continue;
  const hot = cl(1 - (S.camY - q2.b)*.55, 0, 1) * (.5 + .5*lift);   // freshly-laid squares still cooling
  const jit = fr(q2.id*7.3);
  const nx = (X + D2*.5)/width - .5, ny = (Y + D2*.5)/height - .5;
  const nl = Math.hypot(nx,ny) || 1;
  const lam = cl(.5 + .5*((nx/nl)*lgx + (ny/nl)*lgy), 0, 1);
  const q = cl(q2.s/W*2.2, 0, 1);
  const c = faceCol(q, hot*(.6+.5*bass), lam*(.7+.4*jit));
  noStroke();
  if (glow) {                                    // additive cells keep the frame off the luminance floor
    blendMode(ADD);
    fill(c[0], c[1], c[2], cl(7 + 16*lam + 20*hot, 3, 46));
    rect(X, Y, D2, D2);
    blendMode(BLEND);
  } else {
    fill(c[0], c[1], c[2], 100);
    rect(X, Y, D2, D2);
  }
  // engraved hatching -> texture instead of a flat slab
  const nh = Math.round(2 + hw*7*(.5+.5*q));
  if (hw > .04 && D2 > 14) {
    stroke(ic[0], cl(ic[1]*.85,0,100), ic[2], (glow?14:16) + 26*en*hw);
    strokeWeight((u/900)*(.35 + .5*en));
    const diag = (q2.id % 3 === 0);
    for (let h=1;h<=nh;h++){
      const f = h/(nh+1);
      if (diag) line(X, Y + D2*f, X + D2*f, Y);
      else      line(X + D2*f, Y, X + D2*f, Y + D2);
    }
  }
  noFill();
  stroke(ic[0], ic[1], glow ? cl(ic[2]*(.45+.6*lam+.5*hot),0,100) : ic[2], glow ? cl(30+60*hot,10,96) : 62 + 34*en);
  strokeWeight((u/900)*(.8 + 2.1*en)*(glow ? (.6+1.2*hot) : 1));
  rect(X, Y, D2, D2);
  // the order-of-the-square numeral, as on a real dissection plate
  if (P.numerals > .04 && D2 > u*.055) {
    noStroke();
    fill(ic[0], ic[1], glow ? 99 : ic[2], cl(P.numerals,0,1)*(glow?70:80));
    textSize(cl(D2*.26, 7, u*.10));
    text(q2.s, X + D2*.5, Y + D2*.52);
  }
}
// the strip rails
noFill(); stroke(ic[0], ic[1], ic[2], 50 + 30*en); strokeWeight((u/900)*(1.2+1.6*en));
line(0, -height, 0, height*2); line(width, -height, width, height*2);
pop();

// ---- moving chiaroscuro ---------------------------------------------------
const lw2 = 180, lh2 = cl(Math.round(180*height/Math.max(1,width)), 60, 340);
if (!S.lg || S.lgk !== lw2+'x'+lh2) { S.lg = createGraphics(lw2, lh2); S.lg.colorMode(HSB,360,100,100,100); S.lgk = lw2+'x'+lh2; }
const L = S.lg;
L.push(); L.noStroke(); L.blendMode(BLEND);
L.background(0, 0, 100 - (18 + 28*en));
L.blendMode(ADD);
const plx = (.5 + .30*Math.cos(lang))*lw2, ply = (.5 + .26*Math.sin(lang*1.31+1.2))*lh2;
for (let i=0;i<9;i++){
  const q3=i/8, rr=Math.max(lw2,lh2)*(1.26-q3*.98);
  L.fill(0,0,100, (6.5 + 7.5*en + 5*bass)*(.26+.74*q3*q3));
  L.ellipse(plx, ply, rr*2, rr*2);
}
L.blendMode(BLEND); L.pop();
blendMode(MULTIPLY); noStroke(); image(L, 0, 0, width, height); blendMode(BLEND);

// ---- cached plate grain ---------------------------------------------------
const tk = sty+'|'+sd;
if (!S.tex || S.texk !== tk) {
  const tw=420, th=280, t=createGraphics(tw,th);
  t.colorMode(HSB,360,100,100,100); t.background(0,0,100); t.noStroke();
  for (let i=0;i<2200;i++){
    const rr=.4+fr(i*5.37)*1.8;
    t.fill(32, 7, 100-fr(i*6.91)*44, 52);
    t.ellipse(fr(i*2.71)*tw, fr(i*3.19+8.3)*th, rr, rr);
  }
  S.tex = t; S.texk = tk;
}
blendMode(MULTIPLY); noStroke(); image(S.tex, 0, 0, width, height); blendMode(BLEND);

if (P.alpha < 100) { noStroke(); fill(0,0,0, 100 - cl(P.alpha,0,100)); rect(0,0,width,height); }
blendMode(BLEND); drawingContext.shadowBlur = 0;
